-- =============================================================================
-- S46: полные тексты мероприятий 82/85 из D644_26-03 (Приложение 2, 2025-12)
-- → cnInvCmm type=1, group=805 (yr_CmmGr для yr=900)
-- + cnInvCmmCst для 805, если ещё нет
-- DEV only.
-- =============================================================================

SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

BEGIN TRAN;

UPDATE test_sudz.cnInvCmm
SET cnicText = N'Выполнение работ по инвестиционному проекту «КС-9 «Малоперанская». КЦ-2»  в составе стройки «Система магистральных газопроводов Бованенково – Ухта» (код 051-2001061).
Протоколом №61/2025 от 10.12.2025 согласованна коректировка графика выплаты авансов со  сроком погашения в 2027 году. 
По информации Агента актуализированный график выплаты авансов находится на согласовании в Департаменте 644 ПАО "Газпром".'
WHERE cnicInvAccnt = 82 AND cnicType = 1 AND cnicGroup = 805;

UPDATE test_sudz.cnInvCmm
SET cnicText = N'Вступившими в силу решениями Арбитражного суда Иркутской области от 13.10.2021 по делу № А19-16352/2021 и от 19.10.2021 по делу № А19-16343/2021 с ООО «ВМК» в пользу ПАО «Газпром» взыскана сумма неосновательного обогащения в размере 177 869 211,78 руб., проценты за пользование чужими денежными средствами в размере 7 946 386,42 руб., проценты за пользование чужими денежными средствами по день фактического возврата суммы неосновательного обогащения, а также расходы по уплате государственной пошлине в сумме 400 000 руб.
На основании заявлений ПАО «Газпром» Отделом по исполнению особых исполнительных производств Управления Федеральной службы судебных приставов Новосибирской области возбуждены два исполнительных производства № 18125/22/54043-ИП от 11.04.2022, № 25080/22/54043-ИП от 25.05.2022 в отношении ООО «ВМК».
Согласно данным из открытых источников УФССП Новосибирской области в настоящее время в отношении ООО "ВМК" ведется сводное исполнительное производство на общую сумму 325 068 239,17 руб. 12.03.2024 исполнительные производства № 18125/22/98054-ИП от 11.04.2022 № 9587/20/98054-СД, №25080/22/98054-ИП от 25.05.2022 окончены на основании ст. 46 ч. 1 п. 4 ФЗ "Об исполнительном производстве" (у должника отсутствует имущество, на которое может быть обращено взыскание, и все принятые судебным приставом-исполнителем допустимые законом меры по отысканию его имущества оказались безрезультатными).
Направлено письмо 11/012-6084 от 07.03.2024 в ПАО "Газпром" (А.С. Фик) о целесообразности возбуждения банкротного дела в отношении должника. Письмом от 26.04.2024 № 06/44-2161 ПАО "Газпром" дало поручение обратиться в суд с заявлением о признании должника банкротом. Письмом от 21.05.2024 № 11/012-12906 у ПАО "Газпром" запрошена информация: о порядке финансирования расходов ООО "Газпром инвест" в части несения расходов по делу о несостоятельности; размер максимальной суммы расходов (лимит), которую ПАО "Газпром" готово понести; о возможных кандидатурах арбитражных управляющих (при наличии).
13.06.2024 в Арбитражный суд Новосибирской области МИФНС № 17 по Новосибирской области подано заявление о признании ООО "ВМК" банкротом, дело № А45-19974/2024. 13.09.2024 от имени ПАО "Газпром" подано заявление о вступлении в дело о банкротстве и будет рассмотрено в случае введения процедуры наблюдения. 26.11.2024 производство по делу о банкротстве по заявлению МИФНС № 17 по Новосибирской области прекращено в связи с отсутствием у должника денежных средств и имущества, за счет которого возможно финансирование процедуры банкротства. Заявление ПАО "Газпром" о вступлении в дело о банкротстве принято к производству (ПАО "Газпром" финансирует процедуру банкротства).
Определением суда от 16.01.2025 требования ПАО "Газпром" в размере 177 869 211, 78 руб. основной долг, 68 406 025, 79 руб. – проценты за пользование денежными средствами, 400 000 руб. – расходы по уплате государственной пошлины включены в реестр требований должника с отнесением в третью очередь удовлетворения. 
28.07.2025 ООО "ВМК" признано банкротом, открыто конкурсное производство сроком на 6 месяцев до 28.01.2026. По решению суда срок конкурсного производства продлен до 28.07.2026'
WHERE cnicInvAccnt = 85 AND cnicType = 1 AND cnicGroup = 805;

IF NOT EXISTS (SELECT 1 FROM test_sudz.cnInvCmm WHERE cnicInvAccnt=82 AND cnicType=1 AND cnicGroup=805)
    INSERT INTO test_sudz.cnInvCmm (cnicType, cnicGroup, cnicText, cnicInvAccnt)
    VALUES (1, 805, N'Выполнение работ по инвестиционному проекту «КС-9 «Малоперанская». КЦ-2»  в составе стройки «Система магистральных газопроводов Бованенково – Ухта» (код 051-2001061).
Протоколом №61/2025 от 10.12.2025 согласованна коректировка графика выплаты авансов со  сроком погашения в 2027 году. 
По информации Агента актуализированный график выплаты авансов находится на согласовании в Департаменте 644 ПАО "Газпром".', 82);

IF NOT EXISTS (SELECT 1 FROM test_sudz.cnInvCmm WHERE cnicInvAccnt=85 AND cnicType=1 AND cnicGroup=805)
    INSERT INTO test_sudz.cnInvCmm (cnicType, cnicGroup, cnicText, cnicInvAccnt)
    VALUES (1, 805, N'Вступившими в силу решениями Арбитражного суда Иркутской области от 13.10.2021 по делу № А19-16352/2021 и от 19.10.2021 по делу № А19-16343/2021 с ООО «ВМК» в пользу ПАО «Газпром» взыскана сумма неосновательного обогащения в размере 177 869 211,78 руб., проценты за пользование чужими денежными средствами в размере 7 946 386,42 руб., проценты за пользование чужими денежными средствами по день фактического возврата суммы неосновательного обогащения, а также расходы по уплате государственной пошлине в сумме 400 000 руб.
