-- Код стройки года для yr=900 (группа 805), как в D644_26-03
DELETE FROM test_sudz.cnInvCmmCst WHERE ciccCmmGr = 805 AND ciccInvAccnt IN (82, 85);
INSERT INTO test_sudz.cnInvCmmCst (ciccCmmGr, ciccType, ciccCstAgPn, ciccInvAccnt) VALUES
 (805, 2, 1835, 82),
 (805, 2, 2016, 85);

COMMIT TRAN;
GO

SELECT cnicInvAccnt, cnicGroup, LEN(cnicText) L, LEFT(cnicText, 60) txt
FROM test_sudz.cnInvCmm WHERE cnicInvAccnt IN (82,85) AND cnicType=1 AND cnicGroup=805;
SELECT ciccInvAccnt, ciccCstAgPn FROM test_sudz.cnInvCmmCst WHERE ciccCmmGr=805;
GO
